    { id: "c2_l49", question: "Manusia purba jenis Homo Sapiens pertama di Indonesia adalah...", options: ["Homo Wajakensis", "Homo Soloensis", "Homo Floresiensis", "Pithecanthropus", "Meganthropus"], correctAnswer: 0, explanation: "Ditemukan di Tulungagung." },
    { id: "c2_l50", question: "Pembagian kerja berdasarkan keahlian muncul pada zaman...", options: ["Perundagian (Logam)", "Paleolitikum", "Mesolitikum", "Neolitikum", "Batu Tua"], correctAnswer: 0, explanation: "Muncul golongan Undagi." }
