    { id: "c3_m49", question: "Mengapa tradisi megalitikum masih bertahan hingga sekarang (misal di Sumba)?", options: ["Nilai-nilai penghormatan leluhur masih dianggap sangat penting", "Karena mereka tidak mau modern", "Karena sulit menghancurkan batu besar", "Agar dapat uang dari turis saja", "Dipaksa oleh pemerintah"], correctAnswer: 0, explanation: "Kontinuitas budaya." },
    { id: "c3_m50", question: "Bagaimana kaitan antara geografi and kebudayaan prasejarah?", options: ["Lingkungan alam menentukan bahan alat, jenis makanan, and tempat tinggal", "Geografi tidak berpengaruh pada budaya", "Suku yang pintar bisa tinggal di mana saja", "Budaya murni dari pikiran bukan alam", "Hanya masalah keberuntungan"], correctAnswer: 0, explanation: "Determinisme lingkungan awal." }
